"""The named engineering practice, separate from Zawatu's agency services."""
def build(page, a, u, e, form, site, articles, card):
    practices=[
      ('01','Data Engineering','Make data usable, traceable and dependable.','For disconnected sources, fragile reporting and pipelines that need clearer ownership.',['Source-to-report data-flow assessment','Ingestion and transformation pipeline design','Database models, quality checks and recovery approach','Implementation and handover within an agreed scope'],'Python · SQL · PostgreSQL · API integration'),
      ('02','Software Engineering','Build software that teams can maintain.','For backend services, business workflows and integrations that need reliable implementation.',['Backend services and API development','Domain boundaries and authorization workflows','Code review and prioritized remediation','Automated verification and technical documentation'],'Go · Python / FastAPI · REST APIs · PostgreSQL'),
      ('03','System Design & Architecture','Make consequential decisions with context.','For new platforms, system evolution and decisions about integration, hosting and operational responsibility.',['Requirements and current-state assessment','System boundaries and architecture diagrams','Options, trade-offs and decision records','A phased delivery and migration roadmap'],'Business requirements · Data ownership · Reliability · Delivery constraints'),
      ('04','DevOps & Platform Engineering','Improve how systems reach and stay in production.','For manual deployments, inconsistent environments and teams that need a repeatable delivery process.',['CI/CD assessment and pipeline implementation','Container delivery and infrastructure automation','Observability and operational runbooks','Release, recovery and environment-management practices'],'Docker · GitHub Actions / GitLab CI · Terraform · AWS / GCP')
    ]
    intro=f'''<section class="technical-hero wrap"><div><p class="eyebrow">ELVIS NDAYISHIMIYE / ENGINEERING CONSULTING</p><h1>Better systems begin<br>with <em>better decisions.</em></h1><p class="lede">Systems architecture and engineering consulting for businesses, institutions and teams building dependable software and data platforms.</p><p>I help connect business requirements with data design, software implementation and the realities of operating a system.</p><div class="technical-actions"><a class="solid" href="#inquiry">Request an assessment ↗</a><a class="text-link" href="#practices">Explore the practice</a></div></div><aside class="architecture-panel"><span class="eyebrow">FROM CONTEXT TO OPERATION</span><h2>Understand.<br>Design.<br>Build.<br><em>Operate.</em></h2><p>Business purpose<br>Clear system boundaries<br>Explicit trade-offs<br>Practical delivery</p><span class="fine">ADVISORY · ASSESSMENT · IMPLEMENTATION</span></aside></section><div class="scope-bar wrap"><span>DATA ENGINEERING</span><span>SOFTWARE ENGINEERING</span><span>SYSTEM DESIGN</span><span>DEVOPS & PLATFORMS</span></div>'''
    body=intro+'<section class="section wrap" id="practices"><div class="section-top"><span class="eyebrow">01 / PRACTICE AREAS</span><span>THE PROBLEM DEFINES THE WORK</span></div><h2>Engineering depth.<br><em>A business purpose.</em></h2><div class="practice-grid">'
    for num,title,promise,context,deliverables,tools in practices:
      body+=f'<article class="practice-card"><span class="eyebrow">{num} / {title.upper()}</span><h3>{promise}</h3><p>{context}</p><h4>Possible deliverables</h4><ul>'+''.join(f'<li>{x}</li>' for x in deliverables)+f'</ul><p class="practice-tools">{tools}</p></article>'
    body+='</div><p class="fine">Deliverables are selected for each engagement. Existing languages, infrastructure, team capacity and ownership constraints inform the solution.</p></section>'
    body+='''<section class="section wrap soft"><span class="eyebrow">02 / WAYS TO WORK TOGETHER</span><h2>The right engagement.<br><em>At the right depth.</em></h2><div class="engagement-grid"><article><span>01</span><h3>Focused advisory</h3><p>Work through one defined decision, review options and agree practical next steps.</p><p class="fine">Output: discussion notes and agreed recommendations. Preparation is scoped in advance.</p></article><article><span>02</span><h3>Technical assessment</h3><p>Review selected architecture, data flows, source code or delivery practices against your objectives.</p><p class="fine">Output: findings, evidence, priorities and an improvement roadmap within the reviewed scope.</p></article><article><span>03</span><h3>Design & implementation</h3><p>Translate an agreed requirement into architecture, a working component or a delivery improvement.</p><p class="fine">Output: agreed design or implementation, acceptance criteria, documentation and handover.</p></article><article><span>04</span><h3>Ongoing advisory</h3><p>Support architecture decisions, engineering reviews and team development through a defined recurring engagement.</p><p class="fine">Output: scheduled reviews, decision records and progress tracking. Availability and response times are contractual.</p></article></div><p class="fine">Technical fees are quoted according to preparation, complexity and deliverables. The business growth consultation price applies to that separate offer.</p></section>'''
    stages=[('Understand','Clarify the business capability, users, constraints and decision to be made.'),('Assess','Review the agreed evidence and distinguish confirmed findings from assumptions.'),('Design','Compare options and document boundaries, responsibilities and trade-offs.'),('Deliver','Implement or guide the agreed work against explicit acceptance criteria.'),('Review','Verify the result, hand over knowledge and identify the next practical improvements.')]
    body+='<section class="section wrap"><span class="eyebrow">03 / WORKING METHOD</span><h2>From the real requirement<br><em>to an operable system.</em></h2><ol class="method-list">'+''.join(f'<li><h3>{name}</h3><p>{desc}</p></li>' for name,desc in stages)+'</ol></section>'
    body+='''<section class="section wrap profile-section"><div class="profile-mark" aria-hidden="true">EN<span>ENGINEERING<br>WITH CONTEXT</span></div><div><span class="eyebrow">04 / PROFESSIONAL PROFILE</span><h2>Elvis<br><em>Ndayishimiye.</em></h2><p class="lede">Software, platform and data engineering experience, with a growing focus on systems architecture and institutional technology decisions.</p><p>My work brings together backend development, business workflows, database design, cloud infrastructure and software delivery automation. I work from Burundi and welcome relevant remote engagements across borders.</p><p>The architectural direction is deliberate: understand how an organization works, identify what its systems must support, and make technology decisions that teams can implement and sustain.</p><div class="experience-notes"><h3>Relevant areas of experience</h3><ul><li>Operational workflow systems with role-based approvals and reporting requirements.</li><li>Backend APIs and PostgreSQL-based applications.</li><li>Containerized delivery, CI/CD and cloud deployment practices.</li></ul></div><p class="fine">ISARI is a separate independent research initiative focused on institutional architecture. Commercial consulting is scoped and contracted separately.</p></div></section>'''
    tech=[x for x in articles if x.get('track')=='engineering']
    body+='<section class="section wrap"><div class="section-top"><span class="eyebrow">05 / ENGINEERING & SYSTEMS</span>'+a('blog/engineering-systems/','Read the technical journal ↗','text-link')+'</div><h2>Thinking made<br><em>practical.</em></h2><div class="articles">'+''.join(card(x,i) for i,x in enumerate(tech[:3]))+'</div></section>'
    body+=f'''<section class="section wrap soft" id="inquiry"><div class="contact-grid"><div><span class="eyebrow">06 / START WITH THE CHALLENGE</span><h2>What needs<br><em>to work better?</em></h2><p>Describe your current environment, the decision or problem, your expected outcome and timeline. An initial inquiry helps establish fit; a paid engagement begins only after scope and fees are agreed.</p><p>Share a high-level description. Confidential material can be reviewed through an agreed channel after access and confidentiality arrangements are established.</p><a class="text-link" href="mailto:elvis@zawatu.com?subject=Engineering%20consulting%20inquiry">elvis@zawatu.com ↗</a></div>{form('technical',site.get('technical_email','elvis@zawatu.com'))}</div></section>'''
    page('consulting/technical/','Elvis Ndayishimiye — Systems Architecture & Engineering Consulting','Data engineering, software engineering, system design and DevOps consulting. Advisory, technical assessments, implementation and ongoing guidance.',body,'consulting')
